// Extrai comentários do webhook da Meta e mantém só os que têm a palavra QUERO
const out = [];
const vistos = new Set();

for (const item of $input.all()) {
  const body = item.json.body || {};
  if (body.object !== 'instagram') continue;

  for (const entry of body.entry || []) {
    for (const change of entry.changes || []) {
      if (change.field !== 'comments') continue;
      const v = change.value || {};

      // Ignora comentários da própria conta (evita loop com a resposta pública)
      if (v.from?.id === entry.id) continue;

      // Normaliza: remove acentos e deixa maiúsculo -> pega 'quero', 'Quero!!', 'QUERO 😍'
      const texto = (v.text || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase();
      if (!/\bQUERO\b/.test(texto)) continue;

      // Opcional: descomente para responder SÓ em Reels
      // if (v.media?.media_product_type !== 'REELS') continue;

      if (vistos.has(v.id)) continue;
      vistos.add(v.id);

      out.push({
        json: {
          igUserId: entry.id,
          commentId: v.id,
          mediaId: v.media?.id,
          username: v.from?.username,
          texto: v.text,
        },
      });
    }
  }
}

return out;

// Busca o produto do Reels no produtos.json do SITE (o mesmo arquivo que o robô de preços atualiza).
// Assim o Direct sempre manda o link de afiliado e o preço de hoje, sem cadastrar nada no n8n.
//
// Como o bot sabe qual é o produto do vídeo?
//   1) Pelo campo "reels" do produto: lista com o código da URL  instagram.com/reel/CODIGO/
//   2) Se não achar, procura "#id-do-produto" na legenda (ex.: #lixeira-16l)
//   3) Se ainda não achar, manda o link do site com todos os achadinhos

const SITE = 'https://achadinhodahora.pages.dev';

// "?t=" evita pegar uma versão velha guardada em cache
const produtos = await this.helpers.httpRequest({ url: `${SITE}/produtos.json?t=${Date.now()}`, json: true });

// Mesmas regras do script.js do site: vale o preço mais recente com data <= hoje (fuso do Brasil)
const hoje = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Sao_Paulo' });
const brl = v => v.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
function precoDeHoje(p) {
  const validos = (p.precos || []).filter(r => r.data <= hoje).sort((a, b) => a.data.localeCompare(b.data));
  return validos.length ? validos[validos.length - 1].preco : null;
}

return $input.all().map((item, i) => {
  const c = $('Filtrar QUERO').itemMatching(i).json; // dados do comentário
  const { shortcode, permalink, caption = '' } = item.json; // dados do Reels

  const p =
    produtos.find(x => (x.reels || []).includes(shortcode)) ||
    produtos.find(x => caption.includes('#' + x.id));

  let mensagem;
  if (p) {
    const preco = precoDeHoje(p);
    const off = preco && p.precoAntigo ? Math.round((1 - preco / p.precoAntigo) * 100) : 0;
    const linhaPreco = preco ? `💸 Hoje por ${brl(preco)}${off > 0 ? ` (${off}% OFF)` : ''}\n` : '';
    mensagem =
      `Oi @${c.username}! 😍 Aqui está o link da ${p.nome}:\n\n` +
      linhaPreco +
      `👉 ${p.link}\n\n` +
      `O preço pode mudar a qualquer momento no Mercado Livre. Outros achadinhos: ${SITE}`;
  } else {
    mensagem = `Oi @${c.username}! 😍 Todos os achadinhos com link estão aqui:\n\n👉 ${SITE}`;
  }

  return { json: { ...c, shortcode, permalink, produtoId: p ? p.id : null, mensagem } };
});
